DEFAULT_DATA = {
    "users": {},
    "access_requests": {},
    "states": {},
    "training_attempts": {},
    "profile_bindings": {},
    "shifts": {},
    "patrols": {},
    "events": {},
    "defects": {},
    "next_request_id": 1,
    "next_attempt_id": 1,
    "next_shift_id": 1,
    "next_patrol_id": 1,
    "next_event_id": 1,
    "next_defect_id": 1,
}

def utc_now_iso():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def load_data():
    if not DATA_FILE.exists():
        data = json.loads(json.dumps(DEFAULT_DATA))
        save_data(data)
        return data

    try:
        data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
        for key, value in DEFAULT_DATA.items():
            if key not in data:
                data[key] = json.loads(json.dumps(value))
        return data
    except Exception:
        log.exception("Помилка читання локального сховища")
        return json.loads(json.dumps(DEFAULT_DATA))

def save_data(data):
    DATA_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )

def get_user(tg_id):
    return load_data()["users"].get(str(tg_id))

def upsert_user(tg_id, **kwargs):
    data = load_data()
    key = str(tg_id)
    user = data["users"].get(key, {
        "telegram_id": tg_id,
        "username": None,
        "full_name": None,
        "site": None,
        "position": None,
        "role": None,
        "status": "pending",
    })
    for k, v in kwargs.items():
        if v is not None:
            user[k] = v
    data["users"][key] = user
    save_data(data)

def remember_username(tg_id, username):
    if not username:
        return
    user = get_user(tg_id)
    if not user:
        return
    clean = username.lstrip("@")
    if user.get("username") != clean:
        upsert_user(tg_id, username=clean)

def set_state(tg_id, state, payload=None):
    data = load_data()
    data["states"][str(tg_id)] = {
        "state": state,
        "payload": payload or {}
    }
    save_data(data)

def get_state(tg_id):
    item = load_data()["states"].get(str(tg_id))
    if not item:
        return None, {}
    return item.get("state"), item.get("payload", {})

def clear_state(tg_id):
    data = load_data()
    data["states"].pop(str(tg_id), None)
    save_data(data)

def create_access_request(tg_id, username, site, role):
    data = load_data()
    req_id = int(data.get("next_request_id", 1))
    data["next_request_id"] = req_id + 1
    data["access_requests"][str(req_id)] = {
        "id": req_id,
        "telegram_id": tg_id,
        "username": (username or "").lstrip("@") or None,
        "site": site,
        "role": role,
        "status": "new",
        "created_at": utc_now_iso(),
    }
    save_data(data)
    return req_id

def get_access_request(req_id):
    return load_data()["access_requests"].get(str(req_id))

def update_access_request(req_id, status):
    data = load_data()
    row = data["access_requests"].get(str(req_id))
    if row:
        row["status"] = status
        data["access_requests"][str(req_id)] = row
        save_data(data)

def bind_profile(tg_id, identity):
    data = load_data()
    data["profile_bindings"][str(tg_id)] = {
        **identity,
        "bound_at": utc_now_iso()
    }
    user = data["users"].setdefault(str(tg_id), {"telegram_id": tg_id})
    user["site"] = identity["site"]
    user["position"] = identity["position"]
    user["full_name"] = identity["full_name"]
    data["users"][str(tg_id)] = user
    save_data(data)

def save_training_attempt(tg_id, attempt):
    data = load_data()
    attempt_id = int(data.get("next_attempt_id", 1))
    data["next_attempt_id"] = attempt_id + 1
    attempt["id"] = attempt_id
    attempt["telegram_id"] = tg_id
    attempt["finished_at"] = utc_now_iso()
    rows = data["training_attempts"].setdefault(str(tg_id), [])
    rows.append(attempt)
    data["training_attempts"][str(tg_id)] = rows[-50:]
    save_data(data)
    return attempt_id

def get_training_attempts(tg_id):
    return load_data()["training_attempts"].get(str(tg_id), [])

def next_id(data, key):
    value = int(data.get(key, 1))
    data[key] = value + 1
    return value

def get_active_shift(tg_id):
    data = load_data()
    active = [
        row for row in data["shifts"].values()
        if row.get("telegram_id") == tg_id
        and row.get("status") == "active"
    ]
    active.sort(key=lambda x: x.get("started_at") or "", reverse=True)
    return active[0] if active else None

def create_shift(tg_id):
    user = get_user(tg_id) or {}
    existing = get_active_shift(tg_id)
    if existing:
        return existing, False

    data = load_data()
    shift_id = next_id(data, "next_shift_id")
    row = {
        "id": shift_id,
        "telegram_id": tg_id,
        "username": user.get("username"),
        "site": user.get("site"),
        "position": user.get("position") or ROLE_TO_POSITION.get(user.get("role")),
        "full_name": user.get("full_name"),
        "started_at": utc_now_iso(),
        "finished_at": None,
        "status": "active",
    }
    data["shifts"][str(shift_id)] = row
    save_data(data)
    return row, True

def close_shift(tg_id):
    data = load_data()
    active = [
        row for row in data["shifts"].values()
        if row.get("telegram_id") == tg_id
        and row.get("status") == "active"
    ]
    if not active:
        return None

    active.sort(key=lambda x: x.get("started_at") or "", reverse=True)
    row = active[0]
    row["status"] = "finished"
    row["finished_at"] = utc_now_iso()
    data["shifts"][str(row["id"])] = row
    save_data(data)
    return row

def get_active_patrol(tg_id):
    data = load_data()
    rows = [
        p for p in data["patrols"].values()
        if p.get("telegram_id") == tg_id
        and p.get("status") == "active"
    ]
    rows.sort(key=lambda x: x.get("started_at") or "", reverse=True)
    return rows[0] if rows else None

def start_patrol(tg_id):
    shift = get_active_shift(tg_id)
    if not shift:
        return None, "no_shift"

    current = get_active_patrol(tg_id)
    if current:
        return current, "already"

    data = load_data()
    patrol_id = next_id(data, "next_patrol_id")
    row = {
        "id": patrol_id,
        "shift_id": shift["id"],
        "telegram_id": tg_id,
        "site": shift.get("site"),
        "full_name": shift.get("full_name"),
        "started_at": utc_now_iso(),
        "finished_at": None,
        "status": "active",
    }
    data["patrols"][str(patrol_id)] = row
    save_data(data)
    return row, "started"

def finish_patrol(tg_id):
    data = load_data()
    current = get_active_patrol(tg_id)
    if not current:
        return None

    current["status"] = "finished"
    current["finished_at"] = utc_now_iso()
    data["patrols"][str(current["id"])] = current
    save_data(data)
    return current

def create_event(tg_id, category, place, description):
    data = load_data()
    user = get_user(tg_id) or {}
    shift = get_active_shift(tg_id)
    event_id = next_id(data, "next_event_id")

    critical_categories = {
        "Спроба проникнення",
        "Крадіжка / спроба крадіжки",
        "Напад / агресія",
        "Пожежа / дим",
        "Загроза життю / здоров'ю",
    }

    row = {
        "id": event_id,
        "telegram_id": tg_id,
        "username": user.get("username"),
        "full_name": user.get("full_name"),
        "site": user.get("site"),
        "position": user.get("position") or ROLE_TO_POSITION.get(user.get("role")),
        "shift_id": shift.get("id") if shift else None,
        "category": category,
        "place": place,
        "description": description,
        "critical": category in critical_categories,
        "status": "new",
        "created_at": utc_now_iso(),
    }

    data["events"][str(event_id)] = row
    save_data(data)
    return row

def create_defect(tg_id, category, place, description, priority):
    data = load_data()
    user = get_user(tg_id) or {}
    shift = get_active_shift(tg_id)
    defect_id = next_id(data, "next_defect_id")

    row = {
        "id": defect_id,
        "telegram_id": tg_id,
        "username": user.get("username"),
        "full_name": user.get("full_name"),
        "site": user.get("site"),
        "position": user.get("position") or ROLE_TO_POSITION.get(user.get("role")),
        "shift_id": shift.get("id") if shift else None,
        "category": category,
        "place": place,
        "description": description,
        "priority": priority,
        "status": "new",
        "created_at": utc_now_iso(),
    }

    data["defects"][str(defect_id)] = row
    save_data(data)
    return row

