def all_attempts():
    data = load_data()
    rows = []

    for tg_id, attempts in data["training_attempts"].items():
        for attempt in attempts:
            row = dict(attempt)
            row["telegram_id"] = int(tg_id)
            rows.append(row)

    rows.sort(
        key=lambda x: x.get("finished_at") or "",
        reverse=True
    )
    return rows

def latest_attempts_by_identity():
    latest = {}
    for row in all_attempts():
        key = (
            row.get("site"),
            row.get("position"),
            row.get("full_name")
        )
        latest.setdefault(key, row)
    return latest

def my_results_text(tg_id):
    attempts = get_training_attempts(tg_id)

    lines = [
        "🧠 <b>Мої результати</b>",
        ""
    ]

    if not attempts:
        lines.append("📭 Ти ще не завершував тест.")
    else:
        by_name = {}
        for row in attempts:
            by_name.setdefault(row.get("full_name") or "Без ПІБ", []).append(row)

        lines.append("<b>За ПІБ:</b>")

        for full_name, rows in sorted(by_name.items()):
            latest = rows[-1]
            best = max(x.get("percent", 0) for x in rows)
            lines += [
                f"👤 <b>{escape(full_name)}</b>",
                f"🏢 {escape(latest.get('site') or '—')} | "
                f"💼 {escape(latest.get('position') or '—')}",
                f"Останній: <b>{latest.get('percent',0)}%</b> | "
                f"Кращий: <b>{best}%</b> | "
                f"Спроб: {len(rows)}",
                ""
            ]

    lines.append("<b>Загальний рейтинг дільниць:</b>")

    latest = latest_attempts_by_identity()

    ranking = []
    for site in SITES:
        rows = [
            row for row in latest.values()
            if row.get("site") == site
        ]

        if rows:
            avg = round(
                sum(row.get("percent", 0) for row in rows)
                / len(rows)
            )
            ranking.append((avg, site, len(rows)))
        else:
            ranking.append((None, site, 0))

    ranked = sorted(
        [x for x in ranking if x[0] is not None],
        key=lambda x: (-x[0], x[1])
    )

    place = 1
    for avg, site, count in ranked:
        medal = "🥇" if place == 1 else "🥈" if place == 2 else "🥉" if place == 3 else f"{place}."
        lines.append(
            f"{medal} {escape(site)} — <b>{avg}%</b> ({count} ос.)"
        )
        place += 1

    for avg, site, count in ranking:
        if avg is None:
            lines.append(f"▫️ {escape(site)} — тестів немає")

    return "\n".join(lines)

