def admin_stats_text():
    data = load_data()

    active_users = [
        u for u in data["users"].values()
        if u.get("telegram_id") != ADMIN_ID
        and u.get("status") == "active"
    ]

    latest = latest_attempts_by_identity()
    completed = len(latest)

    avg = (
        round(
            sum(a.get("percent",0) for a in latest.values())
            / completed
        )
        if completed else 0
    )

    below = sum(
        1 for a in latest.values()
        if a.get("percent",0) < PASS_PERCENT
    )

    lines = [
        "📊 <b>Статистика знань</b>",
        "",
        f"👥 Активних Telegram-учасників: <b>{len(active_users)}</b>",
        f"👤 ПІБ із результатами: <b>{completed}</b>",
        f"📈 Середній результат: <b>{avg}%</b>",
        f"⚠️ Нижче {PASS_PERCENT}%: <b>{below}</b>",
        "",
        "<b>За дільницями:</b>"
    ]

    for site in SITES:
        rows = [a for a in latest.values() if a.get("site") == site]
        if rows:
            site_avg = round(
                sum(a.get("percent",0) for a in rows) / len(rows)
            )
            lines.append(
                f"• {site} — {len(rows)} ос., середній {site_avg}%"
            )
        else:
            lines.append(f"• {site} — тестів немає")

    lines += ["", "<b>За посадами:</b>"]

    for pos in POSITIONS:
        rows = [a for a in latest.values() if a.get("position") == pos]
        if rows:
            pos_avg = round(
                sum(a.get("percent",0) for a in rows) / len(rows)
            )
            lines.append(
                f"• {pos} — {len(rows)} ос., середній {pos_avg}%"
            )
        else:
            lines.append(f"• {pos} — тестів немає")

    return "\n".join(lines)

def admin_sites_text():
    data = load_data()
    lines = ["🏢 <b>Дільниці</b>", ""]

    for site in SITES:
        connected = sum(
            1 for u in data["users"].values()
            if u.get("telegram_id") != ADMIN_ID
            and u.get("site") == site
        )

        roster = sum(
            1 for s in STAFF_DIRECTORY
            if s.get("site") == site and s.get("active")
        )

        lines.append(
            f"• <b>{site}</b> — підключено {connected}, "
            f"ПІБ у довіднику {roster}"
        )

    lines += [
        "",
        "Поки внесено:",
        "• Біловоди — Циганок Володимир Васильович"
    ]

    return "\n".join(lines)

def admin_knowledge_text():
    counts = {}

    for q in QUESTION_BANK:
        counts[q["topic"]] = counts.get(q["topic"], 0) + 1

    lines = [
        "📚 <b>База знань</b>",
        "",
        f"🎓 Питань у банку: <b>{len(QUESTION_BANK)}</b>",
        f"📝 Питань у тесті: <b>{TEST_QUESTION_COUNT}</b>",
        f"🏢 Об’єктів Біловодів: <b>{len(OBJECTS_BILOVODY)}</b>",
        f"📖 Розділів Процедури: <b>{len(PROCEDURE_SECTIONS)}</b>",
        "",
        "<b>Теми тесту:</b>"
    ]

    for topic, count in counts.items():
        lines.append(f"• {topic} — {count}")

    return "\n".join(lines)

def admin_events_text():
    data = load_data()
    rows = list(data["events"].values())
    rows.sort(key=lambda x: x.get("created_at") or "", reverse=True)

    if not rows:
        return "🚨 Подій поки не зареєстровано."

    lines = ["🚨 <b>Останні події</b>", ""]

    for row in rows[:20]:
        icon = "🔴" if row.get("critical") else "🟡"
        date = (row.get("created_at") or "")[:16].replace("T", " ")
        lines.append(
            f"{icon} №{row['id']} · <b>{escape(row.get('category') or '—')}</b>\n"
            f"🏢 {escape(row.get('site') or '—')} | "
            f"👤 {escape(row.get('full_name') or '@'+str(row.get('username') or '—'))}\n"
            f"📍 {escape(row.get('place') or '—')}\n"
            f"🕒 {date}"
        )

    return "\n\n".join(lines)

def admin_defects_text():
    data = load_data()
    rows = list(data["defects"].values())
    rows.sort(key=lambda x: x.get("created_at") or "", reverse=True)

    if not rows:
        return "⚠️ Недоліків поки не зареєстровано."

    icons = {
        "normal": "🟢",
        "important": "🟡",
        "urgent": "🔴",
    }

    lines = ["⚠️ <b>Останні недоліки</b>", ""]

    for row in rows[:20]:
        date = (row.get("created_at") or "")[:16].replace("T", " ")
        lines.append(
            f"{icons.get(row.get('priority'),'⚪')} №{row['id']} · "
            f"<b>{escape(row.get('category') or '—')}</b>\n"
            f"🏢 {escape(row.get('site') or '—')} | "
            f"👤 {escape(row.get('full_name') or '@'+str(row.get('username') or '—'))}\n"
            f"📍 {escape(row.get('place') or '—')}\n"
            f"Статус: {escape(row.get('status') or 'new')} | 🕒 {date}"
        )

    return "\n\n".join(lines)

def shift_summary_text(tg_id):
    shift = get_active_shift(tg_id)

    if not shift:
        return (
            "📋 <b>Моє чергування</b>\n\n"
            "🔴 Активної зміни немає."
        )

    data = load_data()
    patrols = [
        p for p in data["patrols"].values()
        if p.get("shift_id") == shift["id"]
    ]
    events = [
        e for e in data["events"].values()
        if e.get("shift_id") == shift["id"]
    ]
    defects = [
        d for d in data["defects"].values()
        if d.get("shift_id") == shift["id"]
    ]

    started = (shift.get("started_at") or "")[:16].replace("T", " ")

    return (
        "📋 <b>Моє чергування</b>\n\n"
        f"🟢 Зміна №{shift['id']} активна\n"
        f"🏢 {escape(shift.get('site') or '—')}\n"
        f"👤 {escape(shift.get('full_name') or '@'+str(shift.get('username') or '—'))}\n"
        f"💼 {escape(shift.get('position') or '—')}\n"
        f"🕒 Початок: {started}\n\n"
        f"🚶 Обходів: {len(patrols)}\n"
        f"🚨 Подій: {len(events)}\n"
        f"⚠️ Недоліків: {len(defects)}"
    )

