def handle_callback(cq):
    tg_id = cq["from"]["id"]
    data = cq.get("data","")
    username = cq["from"].get("username")
    remember_username(tg_id, username)

    if data.startswith("quiz:"):
        handle_quiz_callback(cq)
        return

    # ---------- HOME ----------
    if data == "home:user":
        answer_callback(cq["id"])
        user = get_user(tg_id) or {}
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Обери потрібний розділ:",
            main_inline_menu(user.get("role"))
        )
        return

    if data == "home:admin":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🛡 <b>Адміністративна панель</b>\n\n"
            "Обери розділ:",
            admin_inline_menu()
        )
        return

    # ---------- TOP MENUS ----------
    if data == "menu:shift":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🟢 <b>Зміна</b>\n\n"
            "Тут зібрані всі дії під час чергування:",
            shift_menu()
        )
        return

    if data == "menu:training":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Навчання та перевірка знань</b>\n\n"
            f"Тест: {TEST_QUESTION_COUNT} питань.\n"
            f"Цільовий результат: {PASS_PERCENT}%.",
            training_menu()
        )
        return

    if data == "menu:objects":
        answer_callback(cq["id"])
        user = get_user(tg_id) or {}

        if user.get("site") and user.get("site") != "Біловоди":
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                "🏢 Пошук об’єктів поки завантажений "
                "для дільниці <b>Біловоди</b>.\n\n"
                "Інші дільниці додамо після отримання їх Табелів постів.",
                back_home_menu()
            )
            return

        set_state(tg_id, "object_search", {})
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🔎 <b>Пошук об’єкта — Біловоди</b>\n\n"
            "Напиши в чаті назву або частину назви.\n"
            "Наприклад: <b>ворота</b>, <b>автоваг</b>, "
            "<b>КОДА</b>, <b>СВС</b>, <b>генератор</b>.",
            back_home_menu()
        )
        return

    if data == "menu:procedure":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "📖 <b>Процедура з організації охорони об’єктів</b>\n\n"
            "Обери розділ:",
            procedure_keyboard()
        )
        return

    if data == "menu:leadership":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "👔 <b>Керівництво ДЗ і СБ</b>\n\n"
            "Обери розділ:",
            leadership_keyboard()
        )
        return

    # ---------- ACCESS ----------
    if data == "access:start":
        answer_callback(cq["id"])
        start_access_request(
            tg_id,
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data.startswith("access:site:"):
        idx = int(data.rsplit(":",1)[1])
        site = SITES[idx]

        set_state(tg_id, "access_role", {"site": site})
        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🔐 <b>Заявка на доступ</b>\n\n"
            f"🏢 {escape(site)}\n\n"
            "2/2. Обери посаду:",
            role_keyboard("access")
        )
        return

    if data == "access:back:site":
        answer_callback(cq["id"])
        start_access_request(
            tg_id,
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data.startswith("access:role:"):
        role = data.split(":",2)[2]
        state, payload = get_state(tg_id)

        if state != "access_role":
            answer_callback(cq["id"], "Почни заявку заново.")
            return

        submit_access_request(
            tg_id,
            username,
            payload["site"],
            role
        )

        answer_callback(cq["id"], "Заявку відправлено")

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "✅ <b>Заявку сформовано.</b>\n\n"
            "Після погодження адміністратором доступ буде постійним.",
            {"inline_keyboard":[]}
        )
        return

    # ---------- ADMIN APPROVE ----------
    if data.startswith("approve:") or data.startswith("reject:"):
        if tg_id != ADMIN_ID:
            answer_callback(cq["id"], "Недостатньо прав")
            return

        action, req_id = data.split(":",1)
        req = get_access_request(req_id)

        if not req:
            answer_callback(cq["id"], "Заявку не знайдено")
            return

        target = req["telegram_id"]

        if action == "approve":
            update_access_request(req_id, "approved")

            upsert_user(
                target,
                username=req.get("username"),
                site=req.get("site"),
                role=req.get("role"),
                position=ROLE_TO_POSITION.get(req.get("role")),
                status="active"
            )

            send_message(
                target,
                "✅ <b>Доступ надано.</b>\n\n"
                "Повторно подавати заявку більше не потрібно.\n\n"
                f"🏢 {escape(req.get('site') or '—')}\n"
                f"💼 {escape(ROLE_TO_POSITION.get(req.get('role'),'—'))}",
                main_inline_menu(req.get("role"))
            )

            answer_callback(cq["id"], "Доступ надано")

        else:
            update_access_request(req_id, "rejected")
            upsert_user(target, status="rejected")

            send_message(
                target,
                "❌ Заявку на доступ відхилено.",
                unauthorized_menu()
            )

            answer_callback(cq["id"], "Відхилено")

        return

    # ---------- TRAINING ----------
    if data == "training:start":
        answer_callback(cq["id"])
        start_identity_flow(
            tg_id,
            "primary",
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data == "training:repeat":
        answer_callback(cq["id"])
        start_identity_flow(
            tg_id,
            "repeat",
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data == "training:my":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            my_results_text(tg_id),
            training_menu()
        )
        return

    if data == "training:materials":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "📚 <b>Тематичні блоки</b>\n\n"
            "💻 Цифрові технології\n"
            "🏢 Охорона об’єктів\n"
            "🛡 Реагування та затримання\n"
            "🚨 Повітряна тривога\n"
            "🩹 Домедична допомога\n"
            "🔥 Пожежна безпека",
            training_menu()
        )
        return

    # ---------- TEST IDENTITY ----------
    if data.startswith("test:site:"):
        idx = int(data.rsplit(":",1)[1])
        site = SITES[idx]
        state, payload = get_state(tg_id)
        mode = payload.get("mode","primary")

        set_state(
            tg_id,
            "test_role",
            {"mode": mode, "site": site}
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            f"🏢 {escape(site)}\n\n"
            "2/3. Обери посаду:",
            role_keyboard("test")
        )
        return

    if data == "test:back:site":
        state, payload = get_state(tg_id)
        mode = payload.get("mode","primary")
        answer_callback(cq["id"])
        start_identity_flow(
            tg_id,
            mode,
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data.startswith("test:role:"):
        role = data.split(":",2)[2]
        position = ROLE_TO_POSITION.get(role)
        state, payload = get_state(tg_id)

        if state != "test_role":
            answer_callback(cq["id"], "Почни тест заново.")
            return

        site = payload["site"]
        mode = payload.get("mode","primary")
        staff = staff_for(site, position)

        if not staff:
            answer_callback(
                cq["id"],
                "Для цієї дільниці ПІБ ще не завантажені"
            )

            edit_message(
                tg_id,
                cq["message"]["message_id"],
                "📭 <b>Список ПІБ ще не завантажено</b>\n\n"
                f"🏢 {escape(site)}\n"
                f"💼 {escape(position)}\n\n"
                "Пізніше адміністратор додасть повний список.",
                inline([[
                    {
                        "text":"⬅️ Обрати іншу дільницю",
                        "callback_data":"test:restart"
                    }
                ]])
            )
            return

        set_state(
            tg_id,
            "test_staff",
            {
                "mode": mode,
                "site": site,
                "position": position
            }
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            f"🏢 {escape(site)}\n"
            f"💼 {escape(position)}\n\n"
            "3/3. Обери своє ПІБ:",
            staff_keyboard(site, position)
        )
        return

    if data == "test:restart":
        state, payload = get_state(tg_id)
        answer_callback(cq["id"])
        start_identity_flow(
            tg_id,
            payload.get("mode","primary"),
            edit_message_id=cq["message"]["message_id"]
        )
        return

    if data == "test:back:position":
        state, payload = get_state(tg_id)

        site = payload.get("site")
        mode = payload.get("mode","primary")

        set_state(
            tg_id,
            "test_role",
            {"mode": mode, "site": site}
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            "2/3. Обери посаду:",
            role_keyboard("test")
        )
        return

    if data.startswith("test:staff:"):
        staff_id = data.split(":",2)[2]
        state, payload = get_state(tg_id)

        if state != "test_staff":
            answer_callback(cq["id"], "Почни тест заново.")
            return

        person = next(
            (x for x in STAFF_DIRECTORY if x["id"] == staff_id),
            None
        )

        if not person:
            answer_callback(cq["id"], "ПІБ не знайдено")
            return

        expected_username = person.get("telegram_username")

        if expected_username:
            actual = (username or "").lstrip("@").lower()
            if actual != expected_username.lstrip("@").lower():
                answer_callback(
                    cq["id"],
                    "Це ПІБ прив’язане до іншого Telegram"
                )
                return

        identity = {
            "staff_id": person["id"],
            "site": payload["site"],
            "position": payload["position"],
            "full_name": person["full_name"]
        }

        answer_callback(cq["id"], "ПІБ підтверджено")

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "✅ Дані підтверджено.",
            {"inline_keyboard":[]}
        )

        start_quiz(
            tg_id,
            identity,
            payload.get("mode","primary")
        )
        return

    # ---------- SHIFT ----------
    if data == "shift:start":
        row, created = create_shift(tg_id)
        answer_callback(
            cq["id"],
            "Зміну розпочато" if created else "Зміна вже активна"
        )
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            (
                "🟢 <b>Зміну розпочато</b>\n\n"
                if created else
                "🟡 <b>Зміна вже активна</b>\n\n"
            )
            + shift_summary_text(tg_id),
            shift_menu()
        )
        return

    if data == "shift:members":
        answer_callback(cq["id"])
        user = get_user(tg_id) or {}
        text = (
            "👥 <b>Склад зміни</b>\n\n"
            f"👤 {escape(user.get('full_name') or '@'+str(user.get('username') or '—'))}\n"
            f"🏢 {escape(user.get('site') or '—')}\n"
            f"💼 {escape(user.get('position') or ROLE_TO_POSITION.get(user.get('role'),'—'))}\n\n"
            "Повний склад зміни додамо після завантаження всього штатного списку."
        )
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            text,
            shift_menu()
        )
        return

    if data == "shift:patrol":
        current = get_active_patrol(tg_id)
        answer_callback(cq["id"])

        if current:
            text = (
                "🚶 <b>Обхід уже триває</b>\n\n"
                f"Початок: {(current.get('started_at') or '')[:16].replace('T',' ')}"
            )
            kb = inline([
                [{"text":"✅ Завершити обхід","callback_data":"patrol:finish"}],
                [{"text":"⬅️ Назад","callback_data":"menu:shift"}],
            ])
        else:
            text = (
                "🚶 <b>Обхід</b>\n\n"
                "Натисни кнопку, коли фактично починаєш обхід."
            )
            kb = inline([
                [{"text":"🚶 Почати обхід","callback_data":"patrol:start"}],
                [{"text":"⬅️ Назад","callback_data":"menu:shift"}],
            ])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            text,
            kb
        )
        return

    if data == "patrol:start":
        row, status = start_patrol(tg_id)
        answer_callback(cq["id"])

        if status == "no_shift":
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                "⚠️ Спочатку потрібно розпочати зміну.",
                shift_menu()
            )
            return

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🚶 <b>Обхід розпочато</b>\n\n"
            f"Час: {(row.get('started_at') or '')[:16].replace('T',' ')}",
            inline([
                [{"text":"✅ Завершити обхід","callback_data":"patrol:finish"}],
                [{"text":"⬅️ Назад","callback_data":"menu:shift"}],
            ])
        )
        return

    if data == "patrol:finish":
        row = finish_patrol(tg_id)
        answer_callback(cq["id"])

        if not row:
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                "⚠️ Активного обходу немає.",
                shift_menu()
            )
            return

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "✅ <b>Обхід завершено</b>\n\n"
            f"Початок: {(row.get('started_at') or '')[:16].replace('T',' ')}\n"
            f"Завершення: {(row.get('finished_at') or '')[:16].replace('T',' ')}",
            shift_menu()
        )
        return

    if data == "shift:event":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🚨 <b>Нова подія</b>\n\n"
            "Обери тип події:",
            category_keyboard("event", EVENT_CATEGORIES)
        )
        return

    if data.startswith("event:cat:"):
        idx = int(data.rsplit(":",1)[1])
        category = EVENT_CATEGORIES[idx]

        set_state(
            tg_id,
            "event_place",
            {"category": category}
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🚨 <b>Нова подія</b>\n\n"
            f"Категорія: <b>{escape(category)}</b>\n\n"
            "Напиши в чаті <b>місце / об’єкт</b>, де це сталося.",
            back_home_menu()
        )
        return

    if data == "shift:defect":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "⚠️ <b>Новий недолік</b>\n\n"
            "Обери категорію:",
            category_keyboard("defect", DEFECT_CATEGORIES)
        )
        return

    if data.startswith("defect:cat:"):
        idx = int(data.rsplit(":",1)[1])
        category = DEFECT_CATEGORIES[idx]

        set_state(
            tg_id,
            "defect_place",
            {"category": category}
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "⚠️ <b>Новий недолік</b>\n\n"
            f"Категорія: <b>{escape(category)}</b>\n\n"
            "Напиши в чаті <b>об’єкт / місце</b>.",
            back_home_menu()
        )
        return

    if data.startswith("defect:priority:"):
        priority = data.split(":",2)[2]
        state, payload = get_state(tg_id)

        if state != "defect_priority":
            answer_callback(cq["id"], "Почни реєстрацію недоліку заново.")
            return

        row = create_defect(
            tg_id,
            payload["category"],
            payload["place"],
            payload["description"],
            priority
        )

        clear_state(tg_id)
        answer_callback(cq["id"], "Недолік збережено")

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            defect_saved_text(row),
            shift_menu()
        )

        send_message(
            ADMIN_ID,
            "⚠️ <b>Новий недолік</b>\n\n"
            + defect_saved_text(row)
            + f"\n\n🏢 {escape(row.get('site') or '—')}\n"
            + f"👤 {escape(row.get('full_name') or '@'+str(row.get('username') or '—'))}"
        )
        return

    if data == "shift:current":
        answer_callback(cq["id"])
        edit_message(
            tg_id,
            cq["message"]["message_id"],
            shift_summary_text(tg_id),
            shift_menu()
        )
        return

    if data == "shift:end":
        row = close_shift(tg_id)
        answer_callback(cq["id"])

        if not row:
            text = "⚠️ Активної зміни немає."
        else:
            text = (
                "🔴 <b>Зміну завершено</b>\n\n"
                f"Зміна №{row['id']}\n"
                f"Початок: {(row.get('started_at') or '')[:16].replace('T',' ')}\n"
                f"Завершення: {(row.get('finished_at') or '')[:16].replace('T',' ')}"
            )

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            text,
            main_inline_menu((get_user(tg_id) or {}).get("role"))
        )
        return

    # ---------- PROCEDURE ----------
    if data.startswith("proc:"):
        key = data.split(":",1)[1]
        sec = PROCEDURE_SECTIONS.get(key)
        answer_callback(cq["id"])

        if sec:
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                f"📖 <b>{escape(key)}. {escape(sec['title'])}</b>\n\n"
                f"{escape(sec['text'])}",
                procedure_keyboard()
            )
        return

    # ---------- LEADERSHIP ----------
    if data.startswith("lead:"):
        group = data.split(":",1)[1]
        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            show_leadership_text(group),
            leadership_keyboard()
        )
        return

    # ---------- ADMIN ----------
    if data.startswith("admin:"):
        if tg_id != ADMIN_ID:
            answer_callback(cq["id"], "Недостатньо прав")
            return

        section = data.split(":",1)[1]
        answer_callback(cq["id"])

        mapping = {
            "requests": admin_requests_text,
            "users": admin_users_text,
            "results": admin_results_text,
            "stats": admin_stats_text,
            "events": admin_events_text,
            "defects": admin_defects_text,
            "sites": admin_sites_text,
            "knowledge": admin_knowledge_text,
        }

        func = mapping.get(section)
        if func:
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                func(),
                back_home_menu(is_admin=True)
            )
        return

    answer_callback(cq["id"], "Невідома дія")

# =========================================================
# TEXT MESSAGES
# =========================================================

def handle_start(msg):
    tg_id = msg["from"]["id"]
    username = msg["from"].get("username")

    if tg_id == ADMIN_ID:
        upsert_user(
            tg_id,
            username=(username or "").lstrip("@") or None,
            full_name="Адміністратор",
            role="admin",
            status="active"
        )

        remove_old_keyboard(tg_id)

        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Режим адміністратора.\n"
            "Версія: <b>v0.6</b>\n"
            "🧪 Тимчасове сховище без PostgreSQL.",
            admin_inline_menu()
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        remove_old_keyboard(tg_id)

        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Доступ закритий.\n"
            "Подай заявку один раз — після погодження повторна реєстрація не потрібна.",
            unauthorized_menu()
        )
        return

    remember_username(tg_id, username)
    user = get_user(tg_id) or {}

    remove_old_keyboard(tg_id)

    send_message(
        tg_id,
        "🛡 <b>Службовий бот охорони</b>\n\n"
        f"🏢 {escape(user.get('site') or '—')}\n"
        f"💼 {escape(user.get('position') or ROLE_TO_POSITION.get(user.get('role'),'—'))}\n\n"
        "Обери потрібний розділ:",
        main_inline_menu(user.get("role"))
    )

def handle_text(msg):
    tg_id = msg["from"]["id"]
    username = msg["from"].get("username")
    text = (msg.get("text") or "").strip()

    if text == "/start":
        handle_start(msg)
        return

    remember_username(tg_id, username)

    state, payload = get_state(tg_id)

    if state == "quiz":
        send_message(
            tg_id,
            "🎓 Тест уже триває. Відповідай кнопками під питанням."
        )
        return

    # ---------- OBJECT SEARCH ----------
    if state == "object_search":
        results = search_objects(text)

        if not results:
            send_message(
                tg_id,
                "🔎 Нічого не знайдено.\n"
                "Спробуй: <b>ворота</b>, <b>автоваг</b>, "
                "<b>СВС</b>, <b>генератор</b>, <b>ВТЛ</b>.",
                back_home_menu()
            )
        else:
            blocks = [
                f"🔎 <b>Знайдено: {len(results)}</b>"
            ]
            for obj in results:
                blocks.append(object_card(obj))

            send_message(
                tg_id,
                "\n\n".join(blocks),
                back_home_menu()
            )

        clear_state(tg_id)
        return

    # ---------- EVENT FLOW ----------
    if state == "event_place":
        if len(text) < 2:
            send_message(tg_id, "Вкажи місце або об’єкт.")
            return

        payload["place"] = text
        set_state(tg_id, "event_description", payload)

        send_message(
            tg_id,
            "🚨 <b>Подія</b>\n\n"
            f"📍 {escape(text)}\n\n"
            "Тепер коротко опиши, <b>що сталося і які дії виконані</b>."
        )
        return

    if state == "event_description":
        if len(text) < 5:
            send_message(tg_id, "Опиши подію трохи детальніше.")
            return

        row = create_event(
            tg_id,
            payload["category"],
            payload["place"],
            text
        )

        clear_state(tg_id)

        send_message(
            tg_id,
            event_saved_text(row),
            shift_menu()
        )

        admin_text = (
            "🚨 <b>Нова подія</b>\n\n"
            + event_saved_text(row)
            + f"\n\n🏢 {escape(row.get('site') or '—')}\n"
            + f"👤 {escape(row.get('full_name') or '@'+str(row.get('username') or '—'))}"
        )

        if row.get("critical"):
            admin_text = "🔴 <b>КРИТИЧНА ПОДІЯ</b>\n\n" + admin_text

        send_message(ADMIN_ID, admin_text)
        return

    # ---------- DEFECT FLOW ----------
    if state == "defect_place":
        if len(text) < 2:
            send_message(tg_id, "Вкажи об’єкт або місце.")
            return

        payload["place"] = text
        set_state(tg_id, "defect_description", payload)

        send_message(
            tg_id,
            "⚠️ <b>Недолік</b>\n\n"
            f"📍 {escape(text)}\n\n"
            "Коротко опиши, <b>що саме несправне / пошкоджене</b>."
        )
        return

    if state == "defect_description":
        if len(text) < 5:
            send_message(tg_id, "Опиши недолік трохи детальніше.")
            return

        payload["description"] = text
        set_state(tg_id, "defect_priority", payload)

        send_message(
            tg_id,
            "⚠️ <b>Недолік</b>\n\n"
            "Обери пріоритет:",
            defect_priority_keyboard()
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        send_message(
            tg_id,
            "🔐 Доступ не надано.",
            unauthorized_menu()
        )
        return

    send_message(
        tg_id,
        "Оберіть дію кнопками меню.",
        admin_inline_menu() if tg_id == ADMIN_ID else main_inline_menu(user.get("role"))
    )

