@app.get("/")
def health():
    return jsonify({
        "ok": True,
        "service": "security_guard_bot",
        "version": "0.6",
        "storage": "local_json_test_only",
        "training_questions_bank": len(QUESTION_BANK),
        "training_questions_per_test": TEST_QUESTION_COUNT,
        "sites": len(SITES),
        "bilovody_objects": len(OBJECTS_BILOVODY),
        "features": [
            "inline_menu",
            "one_time_access",
            "shift",
            "patrol",
            "events",
            "defects",
            "training",
            "objects",
            "procedure",
            "leadership",
        ]
    })

@app.post(WEBHOOK_PATH)
def telegram_webhook():
    update = request.get_json(silent=True) or {}

    try:
        if "callback_query" in update:
            handle_callback(update["callback_query"])

        elif "message" in update:
            msg = update["message"]

            if "text" in msg:
                handle_text(msg)

    except Exception:
        log.exception("Webhook processing error")

    return jsonify({"ok": True})

def set_webhook():
    if not PUBLIC_URL:
        log.warning("PUBLIC_URL не задано")
        return

    result = tg(
        "setWebhook",
        {"url": f"{PUBLIC_URL}{WEBHOOK_PATH}"}
    )

    log.info("setWebhook: %s", result)

if __name__ == "__main__":
    set_webhook()

    port = int(os.getenv("PORT", "10000"))

    log.info(
        "Starting Security Guard Bot v0.6 on port %s",
        port
    )

    app.run(
        host="0.0.0.0",
        port=port
    )
